#!/usr/bin/env python3
"""
Seeded Monte Carlo benchmark of the geolocation pipeline.

Each run draws a synthetic but physically independent scenario:

* the true microphone somewhere within ``--offset-km`` of the search centre;
* 1-3 audible flyovers (random heading, CPA altitude 300-3000 m, lateral CPA
  offset 0-3 km, speed 110-230 m/s, climb/descent, source tone 350-1200 Hz),
  plus 0-2 decoy aircraft that are in the ADS-B data but silent;
* Doppler events generated by the first-principles forward model in
  ``app.audio.generator`` (iterative travel time, frequency = f0 * d tau/d t),
  **not** by the matcher's own formula, with Gaussian frequency noise and 3 %
  gross outliers;
* nuisance effects the matcher does not know exactly: a uniform wind
  (0-10 m/s, unknown to the matcher), an ADS-B altitude bias (small for
  geometric altitude, QNH-sized for barometric), an air temperature that is
  supplied to the matcher only half of the time, and - when a trusted clock
  is used - a real clock error.

The matcher then runs exactly as the API does (pre-filter, joint matching,
sensitivity, decision).  Outputs: median / p95 localisation error, the
fraction of runs reported ``supported`` and the **false-support rate**
(supported but further than ``precision_target_m`` from the truth), plus
re-scoring of alternative ``DecisionPolicy`` thresholds on the same runs.

    python scripts/benchmark.py --runs 200 --out benchmarks/results
    python scripts/benchmark.py --runs 8 --grid 13 --quiet   # quick look

All randomness derives from ``--seed``; results are reproducible.
"""

from __future__ import annotations

import argparse
import json
import math
import os
import sys
import time
from concurrent.futures import ProcessPoolExecutor
from dataclasses import asdict, dataclass, replace
from typing import Any, Dict, List, Optional

import numpy as np

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

from app.adsb.sample_flights import generate_linear_flight_trajectory, trajectory_start_for_cpa  # noqa: E402
from app.audio.generator import simulate_events  # noqa: E402
from app.physics.confidence import DecisionPolicy, decide_location  # noqa: E402
from app.physics.doppler_engine import DopplerEngine  # noqa: E402
from app.physics.flyover_fit import fit_flyover  # noqa: E402
from app.physics.matching import JointMatcher, MatchOptions  # noqa: E402
from app.physics.prefilter import prefilter_flights  # noqa: E402

CENTER = (37.5585, -122.2711)
T0 = 1_750_000_000.0


@dataclass
class BenchConfig:
    radius_km: float = 8.0
    grid: int = 15
    offset_km: float = 3.0
    duration_s: float = 80.0
    min_flyovers: int = 1
    max_flyovers: int = 3
    max_decoys: int = 2
    noise_hz: tuple = (0.2, 2.0)
    outlier_fraction: float = 0.03
    outlier_run_fraction: float = 0.5  # share of runs whose traces contain gross outliers
    max_wind_mps: float = 10.0
    trusted_clock_fraction: float = 0.5
    clock_error_s: float = 0.3
    clock_tolerance_s: float = 2.0
    precision_target_m: float = 1000.0
    grid_strategy: str = "full"


# Small, fast, fixed subset used as a CI regression gate (tests/test_benchmark_subset.py).
CI_CONFIG = BenchConfig(grid=11, max_flyovers=2, max_decoys=1, duration_s=60.0)
CI_RUNS, CI_SEED = 6, 7
CI_BASELINE = os.path.join(ROOT, "benchmarks", "ci_baseline.json")


def _haversine_m(lat1, lon1, lat2, lon2) -> float:
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp, dl = p2 - p1, math.radians(lon2 - lon1)
    a = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * 6371000.0 * math.asin(math.sqrt(a))


def _offset(lat, lon, east_m, north_m):
    return (lat + math.degrees(north_m / 6371000.0),
            lon + math.degrees(east_m / (6371000.0 * math.cos(math.radians(lat)))))


def make_scenario(seed: int, cfg: BenchConfig) -> Dict[str, Any]:
    rng = np.random.default_rng(seed)
    r = cfg.offset_km * 1000.0 * math.sqrt(rng.uniform())
    th = rng.uniform(0, 2 * math.pi)
    truth = _offset(*CENTER, r * math.sin(th), r * math.cos(th))
    n_fly = int(rng.integers(cfg.min_flyovers, cfg.max_flyovers + 1))
    n_decoy = int(rng.integers(0, cfg.max_decoys + 1))
    rec0 = T0 + float(rng.uniform(0, 1e6))
    flights, audible = [], []
    cpa_fracs = np.sort(rng.uniform(0.2, 0.8, n_fly))
    for i in range(n_fly + n_decoy):
        decoy = i >= n_fly
        heading = float(rng.uniform(0, 360))
        speed = float(rng.uniform(110, 230))
        alt_cpa = float(rng.uniform(300, 3000))
        vr = float(rng.uniform(-8, 8))
        lateral = float(rng.uniform(-3000, 3000))
        before = 90.0
        if decoy:
            # Silent aircraft elsewhere in the area, overlapping the recording in time.
            anchor = _offset(*truth, float(rng.uniform(-6000, 6000)), float(rng.uniform(-6000, 6000)))
            cpa_emit = rec0 + float(rng.uniform(0, cfg.duration_s))
        else:
            anchor = truth
            cpa_emit = rec0 + cpa_fracs[i] * cfg.duration_s - math.hypot(lateral, alt_cpa) / 343.0
        start = trajectory_start_for_cpa(anchor, heading, speed, lateral, before)
        traj = generate_linear_flight_trajectory(
            flight_id=f"{'DCY' if decoy else 'FLY'}{i + 1}", callsign=f"{'DCY' if decoy else 'FLY'}{i + 1}",
            aircraft_type="benchmark", start_lat=start[0], start_lon=start[1], start_alt=alt_cpa - vr * before,
            heading_deg=heading, speed_mps=speed, vertical_rate_mps=vr, duration_sec=2 * before,
            start_epoch=cpa_emit - before, f0_target=float(rng.uniform(350, 1200)), ground_truth_obs=truth)
        traj.pop("ground_truth_mic", None)
        flights.append(traj)
        if not decoy:
            audible.append(traj)
    wind_speed = float(rng.uniform(0, cfg.max_wind_mps))
    wind_dir = float(rng.uniform(0, 2 * math.pi))
    wind = (wind_speed * math.sin(wind_dir), wind_speed * math.cos(wind_dir))
    temp = float(rng.uniform(0, 30))
    rh = float(rng.uniform(0.2, 0.9))
    c_true = DopplerEngine.calculate_speed_of_sound(temp, rh)
    sigma = float(rng.uniform(*cfg.noise_hz))
    outliers = bool(rng.uniform() < cfg.outlier_run_fraction)
    events = simulate_events(audible, truth, rec0, cfg.duration_s, wind, c_true)
    for ev in events:
        n = len(ev["traced_curve"])
        noise = rng.normal(0, sigma, n)
        out = rng.uniform(size=n) < (cfg.outlier_fraction if outliers else 0.0)
        noise[out] += rng.choice([-1, 1], out.sum()) * rng.uniform(10, 30, out.sum())
        for p, e in zip(ev["traced_curve"], noise):
            p["freq"] += float(e)
    basis = "geometric" if rng.uniform() < 0.6 else "barometric"
    alt_bias = float(rng.normal(0, 30) if basis == "geometric" else rng.normal(0, 120))
    adsb = []
    for f in flights:
        g = dict(f, altitudes=[a + alt_bias for a in f["altitudes"]], altitude_basis=basis, data_source="synthetic")
        g.pop("f0_hz", None)
        adsb.append(g)
    trusted = rng.uniform() < cfg.trusted_clock_fraction
    clock_err = float(rng.normal(0, cfg.clock_error_s)) if trusted else None
    return {
        "seed": seed, "truth": truth, "flights": adsb, "events": events, "n_flyovers": len(events),
        "n_flyovers_drawn": n_fly, "n_decoys": n_decoy, "sigma_hz": sigma, "outliers": outliers, "wind_mps": wind_speed,
        "temperature_c": temp, "temperature_known": bool(rng.uniform() < 0.5), "speed_of_sound_true": c_true,
        "altitude_basis": basis, "altitude_bias_m": alt_bias, "clock": "trusted" if trusted else "free",
        "clock_error_s": clock_err, "recording_start": rec0,
    }


def _compact(res: Dict[str, Any], m: JointMatcher) -> Dict[str, Any]:
    """What decide_location needs, JSON-serialisable (for offline policy re-scoring)."""
    if res.get("status") != "ok":
        return {"status": res.get("status")}
    keys = ("event_id", "group_id", "flight_id", "matched", "support_fraction", "rmse_hz", "robust_rmse_hz",
            "outlier_fraction", "drift_at_bound")
    return {
        "status": "ok", "robust_rmse_hz": res["robust_rmse_hz"], "boundary_limited": res["boundary_limited"],
        "diagnostics": [{k: d.get(k) for k in keys} for d in res["diagnostics"]],
        "alternatives": [{"lat": a["lat"], "lon": a["lon"], "robust_rmse_hz": a["robust_rmse_hz"],
                          "distance_from_best_m": a["distance_from_best_m"]} for a in res["alternatives"]],
        "sensitivity": None if res["sensitivity"] is None else
        {"complete": res["sensitivity"]["complete"], "radius_m": res["sensitivity"]["radius_m"]},
    }


def run_one(seed: int, cfg: BenchConfig) -> Dict[str, Any]:
    sc = make_scenario(seed, cfg)
    t_start = time.perf_counter()
    rec = {k: v for k, v in sc.items() if k not in ("flights", "events")}
    rec["truth"] = list(sc["truth"])
    if not sc["events"]:
        rec.update(status="no_events", reason="no_doppler_events", error_m=None)
        return rec
    c = DopplerEngine.calculate_speed_of_sound(sc["temperature_c"], 0.5) if sc["temperature_known"] else 343.2
    clock = None
    if sc["clock"] == "trusted":
        s0 = sc["recording_start"] + sc["clock_error_s"]
        clock = (s0 - cfg.clock_tolerance_s, s0 + cfg.clock_tolerance_s)
    fits = {}
    for ev in sc["events"]:
        pts = ev["traced_curve"]
        try:
            fits[ev["id"]] = fit_flyover([p["time"] for p in pts], [p["freq"] for p in pts], speed_of_sound=c)
        except ValueError:
            pass
    kept, discarded = prefilter_flights(sc["flights"], sc["events"], fits, clock)
    rec["n_discarded"] = len(discarded)
    rec["true_flight_discarded"] = any(d["flight_id"].startswith("FLY") for d in discarded)
    policy = DecisionPolicy(precision_target_m=cfg.precision_target_m)
    if not kept:
        rec.update(status="no_match", reason="no_matching_flights", error_m=None, result={"status": "no_match"})
        return rec
    opts = MatchOptions(speed_of_sound=c, grid_strategy=cfg.grid_strategy)
    m = JointMatcher(kept, sc["events"], CENTER[0], CENTER[1], opts, clock)
    res = m.run(cfg.radius_km, cfg.grid, sensitivity=True, precision_target_m=cfg.precision_target_m)
    decision = decide_location(res, policy, clock_known=clock is not None, n_events=len(sc["events"]))
    rec["status"] = decision["status"]
    rec["reason"] = decision["reason_code"]
    rec["result"] = _compact(res, m)
    if res.get("status") == "ok":
        lat, lon = m.to_geo(res["best"]["x"], res["best"]["y"])
        rec["error_m"] = _haversine_m(lat, lon, *sc["truth"])
        rec["sensitivity_radius_m"] = (res["sensitivity"] or {}).get("radius_m")
        rec["robust_rmse_hz"] = res["robust_rmse_hz"]
        rec["matched_flights"] = sorted({d["flight_id"] for d in res["diagnostics"] if d.get("matched")})
        rec["decoy_matched"] = any(f.startswith("DCY") for f in rec["matched_flights"])
        rec["clock_error_fit_s"] = res["best"]["start"] - sc["recording_start"]
    else:
        rec["error_m"] = None
    rec["runtime_s"] = round(time.perf_counter() - t_start, 2)
    return rec


def _pct(vals, q):
    return float(np.percentile(vals, q)) if len(vals) else None


def summarize(records: List[Dict[str, Any]], target_m: float, label: str = "all") -> Dict[str, Any]:
    n = len(records)
    errs = [r["error_m"] for r in records if r.get("error_m") is not None]
    sup = [r for r in records if r.get("status") == "supported"]
    sup_err = [r["error_m"] for r in sup if r.get("error_m") is not None]
    false_sup = [r for r in sup if r.get("error_m") is None or r["error_m"] > target_m]
    covered = [r for r in sup if r.get("sensitivity_radius_m") is not None and r["error_m"] <= max(r["sensitivity_radius_m"], 1.0)]
    reasons: Dict[str, int] = {}
    for r in records:
        reasons[r.get("reason", "?")] = reasons.get(r.get("reason", "?"), 0) + 1
    return {
        "label": label, "runs": n,
        "with_location": len(errs),
        "median_error_m": _pct(errs, 50), "p95_error_m": _pct(errs, 95),
        "supported": len(sup), "supported_fraction": len(sup) / n if n else None,
        "supported_median_error_m": _pct(sup_err, 50), "supported_p95_error_m": _pct(sup_err, 95),
        "supported_max_error_m": max(sup_err) if sup_err else None,
        "false_supported": len(false_sup),
        "false_support_rate": len(false_sup) / len(sup) if sup else 0.0,
        "false_support_fraction_of_runs": len(false_sup) / n if n else 0.0,
        "sensitivity_radius_coverage": len(covered) / len(sup) if sup else None,
        "reasons": dict(sorted(reasons.items(), key=lambda kv: -kv[1])),
        "false_support_seeds": [r["seed"] for r in false_sup],
    }


def policy_sweep(records: List[Dict[str, Any]], target_m: float) -> List[Dict[str, Any]]:
    """Re-score the stored matcher results under alternative thresholds (same runs, no re-matching)."""
    variants = [(f"default ({DecisionPolicy().name})", {}),
                ("engineering-v1 (plain RMSE gate)", {"residual_metric": "rmse"})]
    for v in (2.0, 4.0, 6.0):
        variants.append((f"max_rmse_hz={v}", {"max_rmse_hz": v}))
    for v in (0.25, 1.0, 2.0):
        variants.append((f"near_tie_hz={v}", {"near_tie_hz": v}))
    for v in (0.15, 0.4):
        variants.append((f"max_outlier_fraction={v}", {"max_outlier_fraction": v}))
    for metric in ("robust", "rmse"):
        for v in (2.0, 3.0):
            variants.append((f"residual_metric={metric}, max_rmse_hz={v}", {"residual_metric": metric, "max_rmse_hz": v}))
    variants.append(("min_independent_flyovers=1", {"min_independent_flyovers": 1}))
    variants.append(("require_sensitivity=True", {"require_sensitivity": True}))
    out = []
    for name, kw in variants:
        pol = replace(DecisionPolicy(precision_target_m=target_m), **kw)
        sup = fs = 0
        for r in records:
            res = r.get("result")
            if not res:
                continue
            d = decide_location(res, pol, clock_known=r.get("clock") == "trusted")
            if d["status"] == "supported":
                sup += 1
                if r.get("error_m") is None or r["error_m"] > target_m:
                    fs += 1
        out.append({"variant": name, "supported": sup, "false_supported": fs,
                    "supported_fraction": sup / len(records) if records else 0.0,
                    "false_support_rate": fs / sup if sup else 0.0})
    return out


def run_benchmark(runs: int, seed: int, cfg: BenchConfig, workers: int = 1, quiet: bool = False) -> Dict[str, Any]:
    seeds = [seed * 100003 + i for i in range(runs)]
    t0 = time.perf_counter()
    if workers > 1:
        import multiprocessing as mp

        ctx = mp.get_context("forkserver" if "forkserver" in mp.get_all_start_methods() else "spawn")
        with ProcessPoolExecutor(max_workers=workers, mp_context=ctx) as pool:
            records = list(pool.map(run_one, seeds, [cfg] * len(seeds)))
    else:
        records = []
        for s in seeds:
            records.append(run_one(s, cfg))
            if not quiet:
                r = records[-1]
                print(f"seed {s}: {r['n_flyovers']} flyover(s) {r['status']:12s} {r.get('reason', ''):32s} "
                      f"err={r['error_m'] if r.get('error_m') is None else round(r['error_m'])} m", flush=True)
    target = cfg.precision_target_m
    summary = {
        "config": asdict(cfg), "runs": runs, "seed": seed, "elapsed_s": round(time.perf_counter() - t0, 1),
        "overall": summarize(records, target),
        "by_flyovers": [summarize([r for r in records if r["n_flyovers"] == k], target, f"{k} flyover(s)")
                        for k in sorted({r["n_flyovers"] for r in records})],
        "by_clock": [summarize([r for r in records if r.get("clock") == k], target, f"clock {k}")
                     for k in ("free", "trusted")],
        "by_altitude_basis": [summarize([r for r in records if r.get("altitude_basis") == k], target, k)
                              for k in ("geometric", "barometric")],
        "by_outliers": [summarize([r for r in records if r.get("outliers") == k], target,
                                  "with outliers" if k else "no outliers") for k in (False, True)],
        "policy_sweep": policy_sweep(records, target),
    }
    return {"summary": summary, "records": records}


def _fmt(v, digits=0):
    if v is None:
        return "–"
    if isinstance(v, float):
        return f"{v:.{digits}f}"
    return str(v)


def markdown(summary: Dict[str, Any]) -> str:
    cfg = summary["config"]
    lines = [
        "# Doppler geolocation benchmark",
        "",
        f"{summary['runs']} seeded Monte Carlo runs (seed {summary['seed']}), grid {cfg['grid']} over "
        f"{cfg['radius_km']} km, precision target {cfg['precision_target_m']:.0f} m, grid strategy "
        f"`{cfg['grid_strategy']}`. Truth from the independent forward model; frequency noise "
        f"{cfg['noise_hz'][0]}–{cfg['noise_hz'][1]} Hz + {cfg['outlier_fraction']:.0%} outliers; unknown wind "
        f"0–{cfg['max_wind_mps']:.0f} m/s; ADS-B altitude bias; trusted clock in "
        f"{cfg['trusted_clock_fraction']:.0%} of runs (error σ {cfg['clock_error_s']} s).",
        "",
        "| subset | runs | supported | false supports | false-support rate | median err (m) | p95 err (m) | "
        "supported median / p95 / max err (m) | radius coverage |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for s in ([summary["overall"]] + summary["by_flyovers"] + summary["by_clock"] + summary["by_altitude_basis"]
              + summary.get("by_outliers", [])):
        if not s["runs"]:
            continue
        lines.append(
            f"| {s['label']} | {s['runs']} | {s['supported']} ({_fmt(100 * s['supported_fraction'])} %) | "
            f"{s['false_supported']} | {_fmt(100 * s['false_support_rate'], 1)} % | {_fmt(s['median_error_m'])} | "
            f"{_fmt(s['p95_error_m'])} | {_fmt(s['supported_median_error_m'])} / {_fmt(s['supported_p95_error_m'])} / "
            f"{_fmt(s['supported_max_error_m'])} | "
            f"{'–' if s['sensitivity_radius_coverage'] is None else _fmt(100 * s['sensitivity_radius_coverage']) + ' %'} |")
    lines += ["", "Outcome reasons (all runs): " + ", ".join(f"`{k}` {v}" for k, v in summary["overall"]["reasons"].items()),
              "", "## Decision-policy sweep (same runs, re-scored)", "",
              "| variant | supported | false supports | false-support rate |", "|---|---|---|---|"]
    for p in summary["policy_sweep"]:
        lines.append(f"| {p['variant']} | {p['supported']} ({_fmt(100 * p['supported_fraction'])} %) | "
                     f"{p['false_supported']} | {_fmt(100 * p['false_support_rate'], 1)} % |")
    lines += ["", "*Radius coverage*: share of supported runs whose true position lies within the reported "
              "sensitivity radius (an engineering envelope, not a calibrated confidence interval).", ""]
    return "\n".join(lines)


def main(argv: Optional[List[str]] = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--runs", type=int, default=100)
    ap.add_argument("--seed", type=int, default=1)
    ap.add_argument("--grid", type=int, default=15)
    ap.add_argument("--strategy", default="full", choices=("full", "coarse_to_fine"))
    ap.add_argument("--workers", type=int, default=max(1, min(4, os.cpu_count() or 1)))
    ap.add_argument("--out", default=None, help="output prefix, writes <out>.json and <out>.md")
    ap.add_argument("--quiet", action="store_true")
    ap.add_argument("--ci", action="store_true", help="run the fixed CI subset (ignores --runs/--seed/--grid)")
    ap.add_argument("--rescore", default=None, help="re-summarise a stored <out>.json under the current DecisionPolicy")
    ap.add_argument("--write-ci-baseline", action="store_true", help="with --ci: store the result as the CI baseline")
    args = ap.parse_args(argv)
    if args.rescore:
        with open(args.rescore) as fh:
            stored = json.load(fh)
        records = stored["records"]
        cfg = BenchConfig(**{k: (tuple(v) if isinstance(v, list) else v) for k, v in stored["summary"]["config"].items()})
        pol = DecisionPolicy(precision_target_m=cfg.precision_target_m)
        for r in records:
            if r.get("result"):
                d = decide_location(r["result"], pol, clock_known=r.get("clock") == "trusted")
                r["status"], r["reason"] = d["status"], d["reason_code"]
        target = cfg.precision_target_m
        summary = dict(stored["summary"], policy=pol.name, overall=summarize(records, target),
                       by_flyovers=[summarize([r for r in records if r["n_flyovers"] == k], target, f"{k} flyover(s)")
                                    for k in sorted({r["n_flyovers"] for r in records})],
                       by_clock=[summarize([r for r in records if r.get("clock") == k], target, f"clock {k}")
                                 for k in ("free", "trusted")],
                       by_altitude_basis=[summarize([r for r in records if r.get("altitude_basis") == k], target, k)
                                          for k in ("geometric", "barometric")],
                       by_outliers=[summarize([r for r in records if r.get("outliers") == k], target,
                                              "with outliers" if k else "no outliers") for k in (False, True)])
        md = markdown(summary).replace("# Doppler geolocation benchmark", f"# Doppler geolocation benchmark (re-scored: {pol.name})")
        out_md = args.rescore[:-5] + f"_{pol.name}.md"
        with open(out_md, "w") as fh:
            fh.write(md)
        print(md)
        print(f"wrote {out_md}")
        return 0
    if args.ci:
        out = run_benchmark(CI_RUNS, CI_SEED, CI_CONFIG, args.workers, args.quiet)
        if args.write_ci_baseline:
            o = out["summary"]["overall"]
            with open(CI_BASELINE, "w") as fh:
                json.dump({"runs": CI_RUNS, "seed": CI_SEED, "config": asdict(CI_CONFIG),
                           **{k: o[k] for k in ("supported", "false_supported", "false_support_rate", "with_location")},
                           "seeds_supported": [r["seed"] for r in out["records"] if r.get("status") == "supported"]},
                          fh, indent=1)
            print(f"wrote {CI_BASELINE}")
        print(markdown(out["summary"]))
        return 0
    cfg = BenchConfig(grid=args.grid, grid_strategy=args.strategy)
    out = run_benchmark(args.runs, args.seed, cfg, args.workers, args.quiet)
    md = markdown(out["summary"])
    print(md)
    if args.out:
        os.makedirs(os.path.dirname(os.path.abspath(args.out)), exist_ok=True)
        with open(args.out + ".json", "w") as fh:
            json.dump(out, fh, indent=1, default=float)
        with open(args.out + ".md", "w") as fh:
            fh.write(md)
        print(f"wrote {args.out}.json and {args.out}.md")
    return 0


if __name__ == "__main__":
    sys.exit(main())
